-- Consumable effects for item use (ItemState, ConsumableData).
-- type: food (Well Fed, +3% EXP), restore (instant HP/MP), medicine (Medicated), cure (removes the
-- listed statuses), script (Battle/Items.lua), unsupported (refused).
-- effects: ';'-separated "modifier:pct:cap" or "modifier:=flat" (Modifier enum ids). Duration and
-- recast come from gamedata_items (effectDuration, recastTime, recastGroup).
DROP TABLE IF EXISTS `server_items_consumable`;
CREATE TABLE `server_items_consumable` (
  `itemId` int(10) unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `type` varchar(16) NOT NULL,
  `statusId` int(10) unsigned NOT NULL DEFAULT '0',
  `effects` varchar(255) NOT NULL DEFAULT '',
  `removeStatus` varchar(64) NOT NULL DEFAULT '',
  `source` varchar(128) NOT NULL DEFAULT '',
  PRIMARY KEY (`itemId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

